import { Logger } from "../../shared/utils/Logger.js";
import { parseTime } from "../../shared/utils/mediaUtils.js";
/**
 * Subtitle Manager
 * Handles parsing and management of WebVTT subtitles.
 */
export class SubtitleManager {
    constructor() {
        this.cues = [];
        this.activeCues = [];
    }

    /**
     * Parse WebVTT or SRT content
     * @param {string} content - VTT or SRT subtitle content
     */
    parse(content) {
        this.cues = [];

        // Normalize SRT to VTT format:
        // - SRT uses commas in timestamps (01:38:58,496), VTT uses periods (01:38:58.496)
        // - Replace comma before milliseconds with period
        const normalizedContent = content.replace(
            /(\d{2}:\d{2}:\d{2}),(\d{3})/g,
            '$1.$2'
        );

        const lines = normalizedContent.split(/\r\n|\n|\r/);
        let currentCue = null;

        // Simple VTT parser
        // Skips header "WEBVTT"
        // Looks for timestamps "00:00:00.000 --> 00:00:05.000"

        for (let i = 0; i < lines.length; i++) {
            const line = lines[i].trim();

            if (!line || line === 'WEBVTT') continue;

            // Skip SRT cue numbers (lines that are just digits, e.g., "1185")
            if (/^\d+$/.test(line)) continue;

            // Check for timestamp line
            const timeMatch = line.match(/(\d{2}:\d{2}:\d{2}\.\d{3}|\d{2}:\d{2}\.\d{3})\s-->\s(\d{2}:\d{2}:\d{2}\.\d{3}|\d{2}:\d{2}\.\d{3})/);

            if (timeMatch) {
                if (currentCue) {
                    this.cues.push(currentCue);
                }

                currentCue = {
                    start: parseTime(timeMatch[1]),
                    end: parseTime(timeMatch[2]),
                    text: ''
                };
            } else if (currentCue) {
                // Append text to current cue
                currentCue.text += (currentCue.text ? '\n' : '') + line;
            }
        }

        if (currentCue) {
            this.cues.push(currentCue);
        }

        Logger.log(`Parsed ${this.cues.length} subtitle cues.`);
    }

    /**
     * Get active cues for a specific time
     * @param {number} time - Current time in seconds
     * @returns {Array} Array of active cue objects
     */
    getActiveCues(time) {
        return this.cues.filter(cue => time >= cue.start && time <= cue.end);
    }


    clear() {
        this.cues = [];
        this.activeCues = [];
    }
}
